    return '<g transform="rotate(' + rot + ' ' + f(cx) + ' ' + f(cy) + ')"><path d="' + p(0) + '" fill="rgba(74,25,66,.16)" transform="translate(.5 .9)"/><path d="' + p(0) + '" fill="' + edge + '"/><path d="' + p(1.1) + '" fill="url(#mypap)"/>'
