    var inner = noLb ? '' : '<div class="' + P + '-lb" style="font-size:' + (sq ? 1.1 : 1.3) + 'cqw">' + (n > 1 ? 'ON THE DRINK MENU' : 'TODAY\'S SPECIAL') + '</div>';
