      var slope = (G.y1 - G.y0) / 100, ang = Math.atan(-slope) * 180 / Math.PI;
      function cut(x, off) { return G.y0 + slope * x + (off || 0); }
      var svg = '<svg class="b03-deco" viewBox="0 0 100 ' + f(HH) + '" preserveAspectRatio="none" aria-hidden="true">'
