    '.c03.sq .c03-tc{text-align:left;padding:1.6cqw 2.4cqw 1.8cqw;box-shadow:0 .4cqw .6cqw rgba(0,0,0,.22),0 .8cqw 0 #b9e08a,0 1.5cqw 0 #3f9e4d,0 1.8cqw .8cqw rgba(0,0,0,.22)}',
