        deco += awning(9, 12);
        o += logo(4.5, 2, partner ? 21 : 17, 10.5) + badge('pb05-badge', 81, 1.6, 15.5);
        o += bx('pb05-kick', 5, 15.2, null, kick, 'font-size:1.55cqw');
