    o += '<g' + SH + '><path d="M' + f(x - w / 2) + ' ' + f(y - w * 0.8) + ' L' + f(x + w / 2) + ' ' + f(y - w * 0.8) + ' L' + f(x + w * 0.38) + ' ' + f(y) + ' L' + f(x - w * 0.38) + ' ' + f(y) + 'Z" fill="' + C.pot + '"/>'
