      + '<ellipse cx="' + f(x - s * 0.5) + '" cy="' + f(y - s * 0.3) + '" rx="' + f(s * 0.55) + '" ry="' + f(s * 0.42) + '" fill="' + C.lemon + '"/>'
      + '<ellipse cx="' + f(x + s * 0.5) + '" cy="' + f(y - s * 0.3) + '" rx="' + f(s * 0.55) + '" ry="' + f(s * 0.42) + '" fill="' + C.lemon + '"/>'
