      + '<rect x="' + f(x - s * 0.07) + '" y="' + f(y - s * 0.6) + '" width="' + f(s * 0.14) + '" height="' + f(s * 1.2) + '" rx="' + f(s * 0.07) + '" fill="' + C.deep + '"/></g>';
