    o += '<path d="' + d + '" fill="' + C.lemon + '"/>';
    o += '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(r) + '" fill="' + C.lemon + '"/><circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(r * 0.74) + '" fill="#fbe57a"/></g>';
