    var qr = '<div class="pc07-qr">' + H.qrImg(spec, partner) + '</div>', bd = '<div class="pc07-bd">' + H.badges(spec, partner) + '</div>';
    var bdg = badge(mon.toUpperCase() + ' ' + spec.year);
