      html += box('pc07-str', sx, 31, sw, st - 30, strings(8, 92));
      html += box('pc07-sign' + (partner ? ' pt' : ''), sx, st, sw, null, card, 'min-height:' + (partner ? 64 : 58) + 'cqw;');
      html += box('pc07-reg', 5, 109.5, 90, null, rg + qr + bd);
